public class BufferComparisonDemo {
    public static void main(String[] args) {
        // 1. StringBuilder: Fast, unsynchronized (Modern default)
        StringBuilder builder = new StringBuilder();
        builder.append("Single-threaded ")
               .append("high performance ")
               .append("buffer.");
        System.out.println("Builder: " + builder.toString());

        // 2. StringBuffer: Thread-safe, synchronized (Legacy)
        StringBuffer buffer = new StringBuffer();
        buffer.append("Multi-threaded ")
              .append("synchronized ")
              .append("buffer.");
        System.out.println("Buffer: " + buffer.toString());

        // 3. Demonstrating API parity
        builder.reverse();
        buffer.reverse();
        System.out.println("Reversed Builder: " + builder.toString());
        System.out.println("Reversed Buffer: " + buffer.toString());

        // 4. Content comparison must use toString()
        StringBuilder s1 = new StringBuilder("Java");
        StringBuffer s2 = new StringBuffer("Java");
        boolean contentMatch = s1.toString().equals(s2.toString());
        System.out.println("Content matches: " + contentMatch); // true
    }
}

